import { TweenLite } from 'gsap';
import { Container, Sprite, Texture } from 'pixi.js';

import { Device } from '@game-studio/device';

import { gameConfig } from '../../models/config-model';
import { inversifyContainer } from '../../inversify/container';
import { userModel } from '../../models/user';
import { eventEmitter } from '../../services/event-emitter';
import { FadeOverlay } from '../fade-overlay';
import { GraphicalSlideManager, IGraphicalSlideManConfig, Slide } from '../slider';

export interface IInfoPopupTextures {
    background: Texture;
    arrow: Texture;
    close: Texture;
}

export class InfoPopup extends Container {
    protected screenFade: FadeOverlay;
    protected cross!: Sprite;
    protected slideView: GraphicalSlideManager;
    protected slidesVisible: boolean;
    private device: Device;
    private defaultConfig: IGraphicalSlideManConfig = { arrowVisibilityCallback: this.shouldShowArrows.bind(this) };

    private hidePromise: Promise<void> | null = null;
    private onHidden: () => void = () => { return;};

    constructor(device: Device, initialSlides: Slide[], textures: IInfoPopupTextures, config?: IGraphicalSlideManConfig) {
        super();

        this.device = device;

        this.screenFade = new FadeOverlay();
        this.createCloseButton(textures.close);

        config = { ...this.defaultConfig, ...config };

        this.slideView = new GraphicalSlideManager(
            initialSlides,
            {
                background: textures.background,
                arrow: textures.arrow
            },
            config);

        this.name = 'htp-view';
        this.addChild(this.screenFade);
        this.addChild(this.slideView);
        this.addChild(this.cross);
        this.hide({ instant: true });

        this.screenFade.interactive = true;
        this.slidesVisible = false;
        this.screenFade.on('pointertap', () => {
            this.hide();
        });
    }

    public resize(width: number, height: number): void {
        this.screenFade.resize(width, height);

        const crossPadding = width * 0.02;
        this.cross.x = (width * 0.5) - crossPadding;
        this.cross.y = -((height * 0.5) - crossPadding);
        this.cross.width = this.cross.height = width * 0.05;

        this.slideView.resize(width, height);

        this.x = width * 0.5;
        this.y = height * 0.5;
    }

    /**
     * Animates the popup on screen
     * @param slides an optional new array of slides can be passed to change what content is shown
     * @returns a Promise which resolves only when the popup is closed
     */
    public async show(slides?: Slide[]): Promise<void> {
        if (this.hidePromise === null) {
            if (slides) {
                this.slideView.setNewSlides(slides);
            }

            this.renderable = true;
            this.interactiveChildren = true;
            TweenLite.to(this, 0.5, {
                alpha: 1,
                onComplete: () => {
                    this.slideView.onShow();
                    this.cross.interactive = true;
                    this.cross.cursor = 'pointer';
                    this.screenFade.interactive = true;
                    this.slidesVisible = true;
                }
            });

            this.hidePromise = new Promise<void>((resolve) => {
                this.onHidden = () => {
                    this.hidePromise = null;
                    resolve();
                };
            });

            eventEmitter.emit('GLOBAL_DIM_SESSION_DATA', true);
        }
        
        return this.hidePromise;
    }

    /**
     * Animates the popup off screen
     * @param args instant can be set to instantly hide the popup instead of animating
     * @returns a Promise which resolves when the panel is fully hidden
     */
    public async hide(args: { instant?: boolean } = {}): Promise<void> {
        this.slideView.onHide();
        this.cross.interactive = false;
        this.cross.cursor = undefined;
        this.screenFade.interactive = false;
        this.slidesVisible = false;

        const fadedAlpha = 0.001;
        this.interactiveChildren = false;
        if (args.instant) {
            this.alpha = fadedAlpha;
            this.onHidden();
            this.renderable = false;
            return Promise.resolve();
        }

        eventEmitter.emit('GLOBAL_DIM_SESSION_DATA', false);

        return new Promise((resolve) => {
            TweenLite.to(this, 0.5, {
                alpha: fadedAlpha,
                onComplete: () => {
                    this.onHidden();
                    this.renderable = false;
                    this.handleFreePlayPopup();
                    resolve();
                }
            });
        });
    }

    private shouldShowArrows(): boolean {
        return this.device.orientation.isLandscape;
    }

    // New players should be shown the FreePlay popup when closing the initial HTP.
    private handleFreePlayPopup(): void {
        if (gameConfig.supportsFreeplays && userModel.freePlayBalance > 0 && inversifyContainer.gameModel.isNewPlayer) {
            eventEmitter.emit('GLOBAL_FREE_PLAY_EARNED', userModel.freePlayBalance);
            inversifyContainer.gameModel.isNewPlayer = false;
        }
    }

    private createCloseButton(close: Texture): void {
        this.cross = new Sprite(close);
        this.cross.name = 'close-button';
        this.cross.anchor.set(1, 0);
        this.cross.on('pointertap', () => this.hide());
    }
}
